function validate([arr]) {
  if (!Array.isArray(arr) || arr.length < 2 || arr.length > 100000) return 'arr needs 2 to 10^5 values.';
  if (arr.length % 2 !== 0) return 'arr must have an even length.';
  if (arr.some(v => !Number.isInteger(v) || v < 1 || v > 100000)) return 'Each value is an integer from 1 to 10^5.';
  return null;
}

