function minSetSize(arr) {
  const count = new Map();
  for (const value of arr) {
    count.set(value, (count.get(value) ?? 0) + 1);
  }

  const frequencies = [...count.values()].sort((a, b) => b - a);
  let removed = 0;
  let chosen = 0;

  while (removed * 2 < arr.length) {
    removed += frequencies[chosen];
    chosen++;
  }
  return chosen;
}

