function minSetSize(arr) {
  const distinct = Array.from(new Set(arr));
  let best = distinct.length;
  for (let mask = 1; mask < 1 << distinct.length; mask++) {
    const picked = new Set(distinct.filter((_, i) => mask & (1 << i)));
    if (picked.size >= best) continue;
    const deleted = arr.filter(v => picked.has(v)).length;
    if (deleted * 2 >= arr.length) best = picked.size;
  }
  return best;
}

