function generate(rand, size) {
  const pick = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  if (size === 'large') {
    const n = 2000;
    const poolSize = rand() < 0.3 ? pick(1, 20) : pick(20, 2000);
    const pool = Array.from({ length: poolSize }, () => pick(1, 100000));
    const skew = 1 + rand() * 3;
    return [Array.from({ length: n }, () => pool[Math.floor(Math.pow(rand(), skew) * poolSize)])];
  }
  const n = 2 * pick(1, 6);
  const high = rand() < 0.75 ? pick(1, 6) : 100000;
  return [Array.from({ length: n }, () => pick(1, high))];
}
